import{_ as a,o as t,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Current GDD visual supplements","description":"The approved current gameplay presentation is now represented by:","frontmatter":{"title":"Current GDD visual supplements","description":"The approved current gameplay presentation is now represented by:","source":"docs/media/gdd/current-visuals/README.md","category":"Other documents","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/media/gdd/current-visuals/readme.md","filePath":"content/docs/media/gdd/current-visuals/readme.md"}'),n={name:"content/docs/media/gdd/current-visuals/readme.md"};function i(s,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<div><h1 id="current-gdd-visual-supplements">Current GDD visual supplements<a class="header-anchor" href="#current-gdd-visual-supplements" aria-label="Link to this section">​</a></h1><h2 id="october-22-approved-isometric-revision">October 22 approved isometric revision<a class="header-anchor" href="#october-22-approved-isometric-revision" aria-label="Link to this section">​</a></h2><p>The approved current gameplay presentation is now represented by:</p><ul><li><code>isometric-exploration.png</code>: fixed orthographic isometric camera, restrained low-poly Chainy environment, small gameplay-scale Explorer, Blocky guide, objectives and mobile movement/interaction controls.</li><li><code>dialogue-overlay.png</code>: the same live isometric world with a bottom dialogue panel, centered choices and Explorer/Blocky portraits at the left and right.</li></ul><p>The three user-supplied Tunic screenshots are camera, lighting, material-density and environment-composition references only. Their maps, characters, creatures, props, icons and HUD are not Chainy assets and must not be copied. The original Chainy storyboards remain the identity reference for the blue-haired yellow-clad Explorer and friendly screen-faced robots.</p><p>These images are design mockups, not screenshots of the current build or import-ready Unity assets. The dialogue question is a placement example and does not freeze the complete Quiz question bank, scoring or retry rules.</p><p>The earlier <code>exploration-guide.png</code> and <code>mini-game-concepts.png</code> are superseded for camera, environment style and dialogue/Quiz layout. They remain historical design records and must not override the October 22 GDD.</p><h3 id="approved-isometric-generation-prompts">Approved isometric generation prompts<a class="header-anchor" href="#approved-isometric-generation-prompts" aria-label="Link to this section">​</a></h3><h4 id="isometric-exploration">Isometric exploration<a class="header-anchor" href="#isometric-exploration" aria-label="Link to this section">​</a></h4><pre><code class="language-text">Use case: style-transfer
Asset type: production-quality Chainy isometric gameplay mockup, 16:9 landscape
Input images: Image 1 is the original rough Chainy overworld edit target; Images 2–4 are the primary camera and low-poly art-direction references; Image 5 is the Chainy character-identity reference.
Primary request: redesign the rough scene into an original Chainy blockchain-world exploration screenshot with a strict fixed orthographic isometric camera, approximately 35–45 degrees top-down. Use restrained low-poly faceted geometry, compact diorama composition, soft painterly materials, sparse detail, angular ruins, water silhouettes, controlled atmospheric color, and long readable shadows. Preserve the blue-haired Explorer in a yellow coat/backpack and friendly white screen-faced Blocky robot, translated into the same low-poly style.
Scene: one connected mossy stone platform surrounded by deep blue water and void, angular stairways, short ruined walls, a narrow bridge, stylized trees and shrubs, and three glowing cyan record-block monuments. Explorer stands small near the center; Blocky waits near a ruin as an interactable guide.
UI: subtle translucent joystick bottom-left and compact button bottom-right reading &quot;INTERACT&quot;.
Constraints: original Chainy setting only; no dialogue overlay; no cube-voxel terrain, oversized toy scenery, cinematic close-up, title screen, collage, copied map/creature/HUD, combat, coins, online icon, watermark, or extra text.
</code></pre><h4 id="dialogue-overlay">Dialogue overlay<a class="header-anchor" href="#dialogue-overlay" aria-label="Link to this section">​</a></h4><pre><code class="language-text">Use case: style-transfer
Asset type: production-quality Chainy dialogue and quiz UI overlay mockup, 16:9 landscape
Input images: Image 1 is the original blockchain quiz edit target; Images 2–4 are the primary camera and low-poly world references; Image 5 is the Chainy character-identity reference.
Primary request: show the dialogue system as UI layered over the live orthographic isometric 3D world, never as a separate scene. In the visible background, the small in-world Explorer and Blocky face each other beside a glowing blockchain record monument on a mossy low-poly ruin island.
UI layout: a wide translucent dark dialogue panel across the bottom 24 percent; the question inside that bottom panel; four compact neutral choice cards stacked vertically in the middle above it; a waist-up Explorer portrait anchored to the left edge and a waist-up Blocky portrait anchored to the right edge. Portraits use Chainy identity with faceted low-poly rendering consistent with the world.
Text (verbatim): speaker &quot;BLOCKY&quot;; dialogue &quot;What is blockchain?&quot;; choices &quot;A. A system that stores information in connected blocks&quot;, &quot;B. A software used to create games&quot;, &quot;C. A tool for editing files&quot;, &quot;D. A type of computer hardware&quot;.
Visual treatment: dark navy translucent panels, thin cyan highlights, cream text, restrained color; all choices neutral.
Constraints: visibly an overlay on the same live world, not a separate visual-novel background or full-screen quiz menu. Bottom dialogue, middle choices, portraits left and right. No correctness cue, selected state, checkmark, score, timer, health, item HUD, joystick, coins, combat, title banner, online icon, watermark, extra text, voxel terrain, or copied map/character.
</code></pre><p>The following concepts were created October 22, 2026 with the built-in image_gen tool (no CLI fallback) for the now-archived mini-game PDF editions. They are historical, not current gameplay or art-treatment requirements. Use the isometric/overlay targets above and the <a href="/Chainy-Docs/content/docs/media/gdd/gameplay-first/readme.html">v2 concept pack</a>. Original generation prompts below remain unchanged as provenance; the guide formerly named Blocky is now Matthew.</p><ul><li><a href="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/exploration-guide.png">Exploration and guide</a>: rounded 3D island, blue-haired yellow-clad explorer and friendly robot. Scene scale, props and camera are illustrative.</li><li><a href="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/mini-game-concepts.png">Mini-game concepts</a>: separate Quiz, Wordle and BlockMatch panels. DATA does not fix word length. Tile count, matching rules, colors and layout remain illustrative. The green Yes button must not be copied as an answer-revealing cue; neutral answer styling is required before submission. The board illustrates tile appearance, not an approved educational matching rule.</li></ul><p>Original references remain the art authority. The flat BlockForge reference is gameplay context only and was not used for styling. Documentation images are not ready-to-import interactive Unity screens. Luis owns production art; Miguel owns UI implementation; Sean owns authored project documentation; Sherwin approves design choices.</p><h2 id="exact-generation-prompts">Exact generation prompts<a class="header-anchor" href="#exact-generation-prompts" aria-label="Link to this section">​</a></h2><h3 id="exploration">Exploration<a class="header-anchor" href="#exploration" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: stylized-concept. Create a new wide landscape 3D game-design illustration for Chainy based on the two attached reference storyboards (style references only). Match their cute rounded toy-like proportions, blue-haired explorer with yellow coat and yellow backpack, gold circular hair detail, friendly white robot with black screen face and cyan eyes, matte rounded voxel island scenery, blue/green foreground and subtle violet technology buildings. One cohesive landscape game view, not a collage. Explorer seen three-quarter from behind on a grassy stone path, robot facing explorer beside a small learning station displaying a book and blue data cube. Open welcoming compact explorable island area. Camera slightly elevated third-person. Generous clear foreground, readable silhouettes, soft warm daylight, polished reference-consistent 3D. No text, UI, currency, trophies, combat, chains to construct, pets, or map locks. This illustrates exploration and guide interaction for offline educational learning, not a finished game screenshot. Aspect ratio about 16:9. Use the provided files as visual references.
</code></pre><h3 id="mini-games">Mini-games<a class="header-anchor" href="#mini-games" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: ui-mockup. Create a polished wide landscape three-panel visual concept sheet for Chainy educational mini-games. The two input storyboards are STYLE references only: match rounded 3D toy-like blue-haired yellow-coated explorer, friendly cyan-eyed white screen-faced robot, blue/green and violet island scenery. Three equal-width panels side by side with clear gutters, each a different activity UI, large legible minimal type. Left header &#39;QUIZ&#39;: friendly robot beside a question card &#39;Can AI make mistakes?&#39; and two large answer buttons &#39;Yes&#39; and &#39;No&#39;; neutral state neither selected. Middle header &#39;WORDLE&#39;: large cream letter tiles spell &#39;D A T A&#39; in a single row with no correctness colors; underneath a compact card reads &#39;Information we can use&#39;. This is an example word, no attempts counter or fixed guess grid. Right header &#39;BLOCKMATCH&#39;: small neat square board of colorful rounded tiles with clearly distinguishable geometric symbols (circles, triangles, squares); no arrows, no selected move, no score, no timer. Board is illustrative only and should not show an implied winning state. Each panel has a soft 3D island backdrop and a simple rounded blue frame. Small consistent footer across bottom &#39;VISUAL CONCEPT - RULES TO BE CONFIRMED&#39;. Clear professional GDD plate, about 16:9. No coins, stars, health, weapons, maps, online icons, purchase options or extra game modes. Preserve reference character proportions; not flat vector art. Panels are separate activities, not simultaneously active gameplay.
</code></pre></div>`,1)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
